package com.nilesh.commerce.product;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.List;
@Service @Transactional class ProductService { private final ProductRepository repository; ProductService(ProductRepository repository){this.repository=repository;} ProductResponse create(CreateProductRequest request){return map(repository.save(new Product(request.name(),request.price(),request.inventory())));} @Transactional(readOnly=true) List<ProductResponse> findAll(){return repository.findAll().stream().map(this::map).toList();} @Transactional(readOnly=true) ProductResponse findById(String id){return map(repository.findById(id).orElseThrow(()->new NotFoundException("Product not found: "+id)));} private ProductResponse map(Product p){return new ProductResponse(p.id,p.name,p.price,p.inventory);} }
record CreateProductRequest(String name, BigDecimal price, int inventory){} record ProductResponse(String id,String name,BigDecimal price,int inventory){}
